def posterior_event(prevalence, tpr, fpr):
    import math

    if any(not math.isfinite(x) or not 0 <= x <= 1 for x in (prevalence, tpr, fpr)):
        raise ValueError("Probabilities in [0,1] required")
    tp, fp = prevalence * tpr, (1 - prevalence) * fpr
    return None if tp + fp == 0 else tp / (tp + fp)


answer = posterior_event(0.01, 0.9, 0.05)
assert abs(answer - 2 / 13) < 1e-12
assert posterior_event(0.01, 0, 0) is None
print(answer)

