import math


def posterior(pi, tpr, fpr):
    if any(not math.isfinite(v) or not 0 <= v <= 1 for v in (pi, tpr, fpr)):
        raise ValueError("Invalid probability")
    tp, fp = pi * tpr, (1 - pi) * fpr
    return None if tp + fp == 0 else tp / (tp + fp)


assert posterior(0.01, 0, 0) is None
answer = posterior(0.01, 0.9, 0.05)
print(answer)
